'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var abs = require( '@stdlib/math/base/special/abs' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var ln = require( '@stdlib/math/base/special/ln' );
var entropy = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof entropy, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', function test( t ) {
	var v = entropy( NaN, 10, 4 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = entropy( 20, NaN, 4 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = entropy( 20, 10, NaN );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` which is not a nonnegative integer, the function returns `NaN`', function test( t ) {
	var v;

	v = entropy( 10.5, 4, 2 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = entropy( -2, 4, 2 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = entropy( PINF, 10, 5 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an `K` which is not a nonnegative integer, the function returns `NaN`', function test( t ) {
	var y;

	y = entropy( 20, 3.5, 10 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( 20, -2, 10 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( 20, PINF, 10 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an `n` which is not a nonnegative integer, the function returns `NaN`', function test( t ) {
	var y;

	y = entropy( 40, 20, 3.5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( 40, 20, -2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( 40, 20, PINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided parameters such that `K > N` or `n > N`, the function returns `NaN`', function test( t ) {
	var y;

	y = entropy( 10, 11, 5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( 10, 5, 11 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns the entropy (N=2, K=1, n=1)', function test( t ) {
	var expected;
	var delta;
	var tol;
	var v;

	v = entropy( 2, 1, 1 );
	expected = ln( 2.0 );
	delta = abs( v - expected );
	tol = 1.0 * EPS * abs( expected );

	t.ok( delta <= tol, 'within tolerance. v: '+v+'. E: '+expected+'. Δ: '+delta+'. tol: '+tol+'.' );
	t.end();
});

tape( 'the function returns the entropy (N=4, K=2, n=2)', function test( t ) {
	var expected;
	var delta;
	var tol;
	var v;

	v = entropy( 4, 2, 2 );

	// -1/3 ln 2 + ln 3
	expected = ( -1.0/3.0 * ln(2.0) ) + ln(3.0);
	delta = abs( v - expected );
	tol = 4.0 * EPS * abs( expected );

	t.ok( delta <= tol, 'within tolerance. v: '+v+'. E: '+expected+'. Δ: '+delta+'. tol: '+tol+'.' );
	t.end();
});
